  vocab=[("semiperímetro", "la mitad del perímetro: es largo + ancho"), ("tabla", "cuadro ordenado con filas y columnas"), ("conclusión", "lo que descubres después de comparar casos"), ("lados naturales", "medidas enteras como 1, 2, 3…")],
