  C=[arith("¿Cuál es el promedio de 4, 4, 4 y 8?", "(4+4+4+8)//4", "La suma es 20 y se divide por 4.", ""),
     arith("El promedio de 4 pruebas debe ser 5 y tres notas son 4, 5 y 5. ¿Cuánto debe ser la cuarta?", "4*5-4-5-5", "El total debe ser 20 y las tres suman 14.", ""),
     ex("¿Cerca de qué número estará el promedio de 9, 10 y 11?", "10", "Los datos están alrededor de 10.")],
  A=[da("Un jugador metió 3, 3, 3, 3 y 6 puntos en cinco partidos. ¿Cuál es su promedio?", "(3+3+3+3+6)/5", "La suma es 18 y se divide por 5.", ""),
     arith("Para tener promedio 6 en 4 pruebas, tienes 5, 6 y 7. ¿Cuánto debe ser la cuarta?", "4*6-5-6-7", "El total debe ser 24 y las tres suman 18.", ""),
     arith("El promedio de 10, 20 y otro dato es 18. ¿Cuál es el otro dato?", "18*3-10-20", "El total debe ser 54 y los dos suman 30.", "")],
  Z=[ex("En una escala de 1 a 7, dos notas son 6,0 y 7,0. ¿Puede el promedio de tres notas llegar a 7,0? Responde sí o no.", "No", "Haría falta una tercera nota de 8, que no existe en la escala."),
     ex("Un grupo tiene datos 4 y 6 y otro grupo tiene 5, 5 y 5. ¿Tienen el mismo promedio? Responde sí o no.", "Sí", "Los dos promedian 5, aunque los datos sean distintos.")],
  D=[arith("El promedio de 5 datos es 12. Si se agrega un sexto dato de 18, ¿cuál es el nuevo promedio?", "(5*12+18)//6", "El total pasa de 60 a 78 y se divide por 6.", ""),
     arith("El promedio de 4 números es 20. Si se quita uno, el promedio de los otros 3 es 18. ¿Qué número se quitó?", "4*20-3*18", "El total era 80 y los tres restantes suman 54.", "")],
