L(OA23, 4,
  mat="Lápiz y papel.",
  use="Aprenderé a ver cómo cambia el promedio cuando un dato cambia mucho y a calcular promedios con decimales. Sirve para saber cuándo el promedio representa bien a un grupo.",
  prior=["Sé calcular el promedio y el dato que falta.", "Sé sumar y dividir decimales sencillos."],
  explain=[
      "El promedio se mueve cuando cambia un dato. Si un dato muy grande se mezcla con otros chicos, el promedio sube mucho y deja de parecerse a la mayoría. Con 10, 12, 14 y 100, el promedio es 136 ÷ 4 = 34, pero casi todos los datos están cerca de 12.",
      "Si un dato sube una cantidad, el promedio sube esa cantidad dividida por el número de datos. Si hay 3 datos y uno sube 6, el promedio sube 6 ÷ 3 = 2. Si todos los datos suben 5, el promedio sube 5.",
      "El promedio puede tener coma. El promedio de 2 y 3 es 2,5. También se aplica a medidas con decimales, como tiempos o temperaturas. Piensa siempre en el contexto: un promedio de 2,5 hijos por familia no significa que haya medio hijo.",
  ],
  vocab=[("dato extremo", "dato mucho mayor o mucho menor que casi todos los demás"), ("representar", "describir bien a un grupo"), ("contexto", "la situación de donde vienen los datos"), ("decimal", "número con coma, como 2,5")],
  worked=[
      ("Un dato extremo", "Los datos son 10, 12, 14 y 100. Calcula el promedio y el promedio sin el 100.", ["Con el 100: (10 + 12 + 14 + 100) ÷ 4 = 136 ÷ 4 = 34.", "Sin el 100: (10 + 12 + 14) ÷ 3 = 36 ÷ 3 = 12."], "34 con el 100 y 12 sin él"),
      ("Promedio con coma", "Los tiempos de dos carreras fueron 12,4 s y 11,6 s. ¿Cuál es el promedio?", ["Sumo: 12,4 + 11,6 = 24,0.", "Divido por 2: 24 ÷ 2 = 12."], "12 s"),
  ],
  mist=[
      ("Decir que el promedio 34 representa bien al grupo 10, 12, 14 y 100.", "No se mira que un dato es muy distinto de los demás.", "Casi todos los datos están cerca de 12, no de 34."),
      ("Pensar que si el promedio es 2,5 hijos hay familias con medio hijo.", "Se interpreta el promedio como un dato real.", "El promedio es un resumen del grupo: no tiene por qué ser un valor posible."),
  ],
  R=[arith("¿Cuál es el promedio de 10, 12 y 14?", "(10+12+14)//3", "La suma es 36 y se divide por 3.", ""),
     ex("Si agregas un dato igual a 12 a los datos 10, 12 y 14, ¿el promedio cambia? Responde sí o no.", "No", "El promedio sigue siendo 12."),
     da("¿Cuál es el promedio de 2 y 3?", "(2+3)/2", "La suma es 5 y se divide por 2.", "")],
  C=[arith("Calcula el promedio de 8, 10, 12 y 90.", "(8+10+12+90)//4", "La suma es 120 y se divide por 4.", ""),
     arith("Calcula el promedio de 8, 10 y 12, sin el 90.", "(8+10+12)//3", "La suma es 30 y se divide por 3.", ""),
     ex("¿Está el promedio 30 cerca de la mayoría de los datos 8, 10, 12 y 90? Responde sí o no.", "No", "Casi todos los datos están cerca de 10.")],
  A=[da("Las temperaturas de cuatro horas fueron 18,5; 20,5; 19,5 y 21,5 °C. ¿Cuál es el promedio?", "(18.5+20.5+19.5+21.5)/4", "La suma es 80 y se divide por 4.", " °C"),
     arith("Tres productos cuestan $850, $1.150 y $1.000. ¿Cuál es el precio promedio?", "(850+1150+1000)//3", "La suma es 3.000 y se divide por 3.", " pesos"),
     da("Los tiempos de dos carreras fueron 10,8 s y 9,2 s. ¿Cuál es el promedio?", "(10.8+9.2)/2", "La suma es 20 y se divide por 2.", " s")],
  Z=[arith("Hay 3 datos y uno de ellos sube 6 unidades. ¿Cuántas unidades sube el promedio?", "6//3", "El aumento se reparte entre los 3 datos.", " unidades"),
     ex("Si todos los datos de un grupo suben 5 unidades, ¿cuántas unidades sube el promedio?", "5", "Todos suben lo mismo, y el promedio también.")],
  D=[arith("Cuatro datos tienen promedio 12,5. ¿Cuánto suman?", "125*4//10", "12,5 × 4 = 50.", ""),
     da("¿Cuál es el promedio de 0,5; 1,5 y 2,5?", "(0.5+1.5+2.5)/3", "La suma es 4,5 y se divide por 3.", "")],
  ctx=[arith("Llovió 12, 8, 0, 4 y 16 mm en cinco días. ¿Cuántos milímetros llovió en promedio por día?", "(12+8+0+4+16)//5", "La suma es 40 y se divide por 5.", " mm")],
  chk=[arith("¿Cuál es el promedio de 20, 22 y 24?", "(20+22+24)//3", "La suma es 66 y se divide por 3.", ""),
       ex("Si un dato muy grande se agrega a una lista de datos chicos, ¿el promedio sube o baja?", "Sube", "El total aumenta mucho."),
       da("¿Cuál es el promedio de 1,2 y 1,8?", "(1.2+1.8)/2", "La suma es 3 y se divide por 2.", "")],
  open=("Cinco amigos tienen $1.000, $1.200, $1.100, $900 y $5.000 en la alcancía. Calcula el promedio con los cinco, luego sin el que tiene $5.000, y escribe cuál de los dos describe mejor a la mayoría y por qué.",
        "Con los cinco: 9.200 ÷ 5 = 1.840. Sin $5.000: 4.200 ÷ 4 = 1.050. El segundo describe mejor a la mayoría porque casi todos tienen cerca de $1.000.",
        ["calcula los dos promedios", "compara con los datos", "justifica cuál describe mejor"],
        ["dos promedios", "justificación"],
        ["no mirar el dato extremo", "dividir por la cantidad equivocada"],
        "Pide que explique el efecto del dato grande. Reconoce la justificación."),
  reinforce="Calcula el promedio de 5, 6, 7 y luego de 5, 6, 7 y 30, y compara.",
  extend="Explica con un ejemplo por qué el promedio puede no parecerse a ningún dato.")

L(OA23, 5,
  mat="Lápiz y papel. Las notas se escriben en la escala de 1,0 a 7,0.",
  use="Aprenderé a comprobar, comparar e interpretar promedios en su contexto, por ejemplo con notas. Sirve para decidir si una afirmación sobre un promedio es correcta.",
  prior=["Sé calcular promedios con enteros y con decimales.", "Sé que el promedio resume un grupo, no a cada persona."],
  explain=[
      "Para comparar dos grupos, calcula el promedio de cada uno y compáralos. Un grupo con promedio 6,5 tiene en general mejores resultados que uno con promedio 6,0, pero no todos sus datos son mayores.",
      "Dos grupos pueden tener el mismo promedio y ser muy distintos. El grupo 4, 6 y 8 y el grupo 5, 6 y 7 promedian 6. Los datos del segundo están más cerca del 6 y lo representa mejor.",
      "Para interpretar, escribe una frase con el contexto: «En promedio, cada familia tiene 2 hijos» no significa que todas tengan 2; puede haber una con 0. Comprueba el cálculo con otra estrategia: la suma de lo que sobra sobre el promedio debe igualar lo que falta bajo él.",
  ],
  vocab=[("interpretar", "explicar qué significa un resultado en su situación"), ("comparar", "mirar dos resultados para ver cuál es mayor o menor"), ("escala de notas", "valores posibles de una nota, de 1,0 a 7,0"), ("comprobar", "revisar un resultado con otra estrategia")],
  worked=[
      ("Promedio de notas", "Las notas de Joaquín son 5,5; 6,0 y 6,5. ¿Cuál es su promedio?", ["Sumo: 5,5 + 6,0 + 6,5 = 18,0.", "Divido por 3: 18 ÷ 3 = 6."], "6,0"),
      ("Mismo promedio", "El grupo A tiene 4, 6 y 8 y el grupo B tiene 5, 6 y 7. ¿Qué promedios tienen?", ["Grupo A: (4 + 6 + 8) ÷ 3 = 18 ÷ 3 = 6.", "Grupo B: (5 + 6 + 7) ÷ 3 = 18 ÷ 3 = 6."], "Los dos promedian 6, pero los datos de B están más juntos"),
  ],
  mist=[
      ("Decir que si el promedio es 6 todos sacaron 6.", "Se interpreta el promedio como un valor de todos.", "Puede haber notas más altas y más bajas que compensan."),
      ("Concluir que el grupo con mayor promedio siempre tiene todas las notas mejores.", "Se compara el resumen y no cada dato.", "El promedio mayor no garantiza que cada dato sea mayor."),
  ],
  R=[da("¿Cuál es el promedio de las notas 6,0 y 5,0?", "(6.0+5.0)/2", "La suma es 11 y se divide por 2.", ""),
     ex("El equipo A tiene promedio 8 y el equipo B tiene promedio 6. ¿Cuál tiene mayor promedio?", "El equipo A", "8 es mayor que 6."),
     da("¿Cuál es el promedio de las notas 4,0; 5,0 y 6,0?", "(4.0+5.0+6.0)/3", "La suma es 15 y se divide por 3.", "")],
  C=[da("¿Cuál es el promedio de las notas 4,5; 5,5 y 6,5?", "(4.5+5.5+6.5)/3", "La suma es 16,5 y se divide por 3.", ""),
     ex("El grupo A tiene 3, 6 y 9 y el grupo B tiene 5, 6 y 7. ¿Tienen el mismo promedio? Responde sí o no.", "Sí", "Los dos suman 18 y promedian 6."),
     ex("Si el promedio de notas de un curso es 6,0, ¿todos sacaron 6,0? Responde sí o no.", "No", "El promedio resume el grupo; las notas individuales pueden variar.")],
  A=[da("Las notas de Joaquín son 5,0; 6,0; 7,0 y 6,0. ¿Cuál es su promedio?", "(5.0+6.0+7.0+6.0)/4", "La suma es 24 y se divide por 4.", ""),
     ex("Ana tiene notas 6,5; 6,0 y 5,5, y Luis tiene 6,0; 6,5 y 7,0. ¿Quién tiene mayor promedio?", "Luis", "Ana promedia 6,0 y Luis promedia 6,5."),
     ex("Dos cursos tienen promedio de edad 10 años. ¿Es seguro que haya estudiantes de 10 años en cada curso? Responde sí o no.", "No", "El promedio puede no coincidir con ninguna edad.")],
  Z=[ex("«En promedio, cada familia de un edificio tiene 2 hijos.» ¿Puede haber una familia sin hijos? Responde sí o no.", "Sí", "El promedio es un resumen del grupo."),
     ex("El grupo 1 tiene 1, 1 y 10 y el grupo 2 tiene 4, 4 y 4. Los dos promedian 4. ¿Cuál representa mejor a sus integrantes?", "El grupo 2", "Todos sus datos están en 4; en el grupo 1 hay un dato muy lejano.")],
  D=[da("Para mantener un promedio de 6,0 en tres pruebas, tienes 5,5 y 6,0. ¿Qué nota necesitas en la tercera?", "18-5.5-6.0", "El total debe ser 18 y las dos notas suman 11,5.", ""),
     ex("El promedio de 4 notas es 5,5. ¿Puede subir a 6,0 con una quinta nota de máximo 7,0? Responde sí o no.", "No", "El total es 22; con 7,0 serían 29 y 29 ÷ 5 = 5,8.")],
  ctx=[ex("El tiempo de estudio promedio de un curso es 40 minutos diarios. Gaspar estudia 30 minutos. ¿Estudia más o menos que el promedio?", "Menos", "30 es menor que 40.")],
  chk=[da("¿Cuál es el promedio de 7,0 y 5,0?", "(7.0+5.0)/2", "La suma es 12 y se divide por 2.", ""),
       ex("El promedio de un curso A es 5,8 y el de un curso B es 6,2. ¿Cuál es mayor?", "El del curso B", "6,2 es mayor que 5,8."),
       ex("Un promedio de 2,5 hijos por familia, ¿significa que alguna familia tiene medio hijo? Responde sí o no.", "No", "Es un resumen, no un dato real.")],
  open=("Elige un par de grupos: A) notas 5,0; 6,0; 7,0 contra notas 6,0; 6,0; 6,0 o B) puntajes 10, 20, 30 contra puntajes 15, 20, 25. Calcula el promedio de cada grupo, di si son iguales y escribe una frase que interprete el resultado y diga cuál grupo está más parejo.",
        "A) Los dos promedian 6,0. El segundo grupo está más parejo porque todas sus notas son 6,0. Interpretación: en promedio los dos grupos tienen 6,0, pero el primero tiene notas más distintas.",
        ["calcula los dos promedios", "compara", "interpreta con una frase", "dice cuál grupo es más parejo y por qué"],
        ["dos promedios", "frase de interpretación"],
        ["decir que todos tienen el promedio", "no mirar cuán distintos son los datos"],
        "Pide que explique cómo supo cuál grupo era más parejo. Reconoce que no afirme que todos sacaron el promedio."),
  reinforce="Calcula el promedio de las notas de tres pruebas imaginarias que elijas y escribe qué significa.",
  extend="Explica con un ejemplo por qué dos grupos con el mismo promedio pueden ser muy distintos.")
